function Assert-ExactProperties {param([object]$Value,[string[]]$Expected,[string]$Description)$a=@($Value.PSObject.Properties.Name|Sort-Object);$w=@($Expected|Sort-Object);if($a.Count-ne$w.Count){throw "$Description has missing or unknown properties."};for($i=0;$i-lt$w.Count;$i++){if($a[$i]-cne$w[$i]){throw "$Description has missing or unknown properties."}}}
function Assert-JsonTypes {param([object]$Value,[string[]]$Booleans=@(),[string[]]$Integers=@(),[string[]]$Strings=@(),[string]$Description)foreach($n in $Booleans){if($Value.PSObject.Properties[$n].Value-isnot[bool]){throw "$Description '$n' must be a JSON boolean."}};foreach($n in $Integers){$v=$Value.PSObject.Properties[$n].Value;if($v-isnot[int32]-and$v-isnot[int64]-and$v-isnot[uint32]-and$v-isnot[uint64]-and$v-isnot[int16]-and$v-isnot[uint16]-and$v-isnot[byte]-and$v-isnot[sbyte]){throw "$Description '$n' must be a JSON integer."}};foreach($n in $Strings){if($Value.PSObject.Properties[$n].Value-isnot[string]){throw "$Description '$n' must be a JSON string."}}}
function Assert-ContainedNonReparsePath {param([string]$Path,[string]$Description)$full=[IO.Path]::GetFullPath($Path);$prefix=$repoRoot.TrimEnd('\')+'\';if(-not$full.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)){throw "$Description must stay inside the repository."};$current=$repoRoot;foreach($part in @($full.Substring($prefix.Length).Split('\')|Where-Object{$_.Length})){$current=Join-Path $current $part;if(-not(Test-Path -LiteralPath $current)){throw "$Description component is missing."};if((Get-Item $current -Force).Attributes-band[IO.FileAttributes]::ReparsePoint){throw "$Description traverses a reparse point."}};$full}
function Assert-ExactChildren {param([string]$Root,[string[]]$Expected,[string]$Description)$a=@((Get-ChildItem $Root -Force|Sort-Object Name).Name);$w=@($Expected|Sort-Object);if($a.Count-ne$w.Count){throw "$Description has missing or extra children."};for($i=0;$i-lt$w.Count;$i++){if($a[$i]-cne$w[$i]){throw "$Description has incorrectly named children."}}}
function Get-TreeSnapshot {param([string]$Root)$items=@(Get-ChildItem $Root -Recurse -Force);$entries=@();$files=@($items|Where-Object{-not$_.PSIsContainer}|Sort-Object FullName);foreach($i in @((Get-Item $Root -Force))+$items){if($i.Attributes-band[IO.FileAttributes]::ReparsePoint){throw 'Evidence or source tree contains a reparse point.'}};foreach($d in @($items|Where-Object PSIsContainer|Sort-Object FullName)){$entries+=[ordered]@{kind='directory';path=$d.FullName.Substring($Root.Length).TrimStart('\').Replace('\','/')}};foreach($f in $files){$entries+=[ordered]@{kind='file';path=$f.FullName.Substring($Root.Length).TrimStart('\').Replace('\','/');length=$f.Length;sha256=(Get-FileHash $f.FullName -Algorithm SHA256).Hash}};$json=ConvertTo-Json -InputObject @($entries) -Depth 4 -Compress;$sha=[Security.Cryptography.SHA256]::Create();try{$hash=-join($sha.ComputeHash($utf8.GetBytes($json))|ForEach-Object{$_.ToString('X2')})}finally{$sha.Dispose()};$bytes=0L;foreach($f in $files){$bytes+=[long]$f.Length};[pscustomobject]@{Hash=$hash;FileCount=$files.Count;DirectoryCount=@($items|Where-Object PSIsContainer).Count;Bytes=$bytes}}
function Get-RuntimeLogSet {param([string]$CurrentLogPath)if((Split-Path -Leaf $CurrentLogPath)-cne'mcla.log'){throw 'Current runtime log must be named mcla.log.'};$files=@(Get-ChildItem (Split-Path -Parent $CurrentLogPath) -File -Force -Filter 'mcla*.log');if($files.Count-lt1-or$files.Count-gt16){throw 'Runtime log set must contain 1-16 files.'};$current=@($files|Where-Object{$_.Name-ceq'mcla.log'});if($current.Count-ne1){throw 'Runtime log set requires exactly one mcla.log.'};$rot=@();foreach($f in $files){if($f.Attributes-band[IO.FileAttributes]::ReparsePoint){throw 'Runtime log is a reparse point.'};if($f.Name-ceq'mcla.log'){continue};$m=[regex]::Match($f.Name,'^mcla\.([1-9][0-9]*)\.log$');if(-not$m.Success){throw 'Malformed runtime log rotation name.'};$rot+=[pscustomobject]@{N=[int]$m.Groups[1].Value;F=$f}};$ids=@($rot|ForEach-Object{$_.N}|Sort-Object);for($i=0;$i-lt$ids.Count;$i++){if($ids[$i]-ne$i+1-or$ids[$i]-gt15){throw 'Runtime log rotations are not contiguous.'}};$ordered=@($rot|Sort-Object N -Descending|ForEach-Object{$_.F})+$current;$manifest=@();$parts=@();$bytes=0L;$previous=[datetime]::MinValue;foreach($f in $ordered){if($f.Length-gt8388608-or$f.LastWriteTimeUtc-lt$previous){throw 'Runtime log size or chronology failed.'};$previous=$f.LastWriteTimeUtc;$bytes+=$f.Length;if($bytes-gt100663296){throw 'Runtime logs exceed 96 MiB.'};$manifest+=[ordered]@{name=$f.Name;bytes=$f.Length;sha256=(Get-FileHash $f.FullName -Algorithm SHA256).Hash};$parts+=[IO.File]::ReadAllText($f.FullName)};$json=ConvertTo-Json -InputObject @($manifest) -Depth 3 -Compress;$sha=[Security.Cryptography.SHA256]::Create();try{$hash=-join($sha.ComputeHash($utf8.GetBytes($json))|ForEach-Object{$_.ToString('X2')})}finally{$sha.Dispose()};[pscustomobject]@{Files=@($manifest);Count=$manifest.Count;Bytes=$bytes;Hash=$hash;Text=($parts-join[Environment]::NewLine)}}
function Get-GameIdentity {$root=Assert-ContainedNonReparsePath $canonicalGame 'Canonical game tree';$manifest=Assert-ContainedNonReparsePath (Join-Path $repoRoot 'private/game-manifest.json') 'Canonical game manifest';$tree=Get-TreeSnapshot $root;$v=&$gameVerifier -GamePath $root -ManifestPath $manifest -VerifyHashes;[pscustomobject]@{file_count=$v.FileCount;payload_bytes=$v.PayloadBytes;hashes_verified=$v.HashesVerified;manifest_sha256=(Get-FileHash $manifest -Algorithm SHA256).Hash;tree_sha256=$tree.Hash;tree_file_count=$tree.FileCount;tree_directory_count=$tree.DirectoryCount;tree_bytes=$tree.Bytes}}
