function Get-DigitalEvidenceProbe {param([string]$RunId,[string]$OverrideRoot)
 if($RunId-cne$canonicalDigitalRun){throw 'Digital evidence run id is not the accepted immutable run.'}
 $root=if($OverrideRoot){Assert-ContainedNonReparsePath $OverrideRoot 'Digital evidence fixture root'}else{Assert-ContainedNonReparsePath (Join-Path $repoRoot "private/evidence/M4-006/$RunId") 'Canonical digital evidence root'}
 Assert-ExactChildren $root @('runs','sdk-install.log','sdk-input-test.log','relwithdebinfo-clean-build.log') 'Digital evidence root';$runs=Join-Path $root 'runs';Assert-ExactChildren $runs @('01') 'Digital evidence runs root';$cycle=Join-Path $runs '01';$logPath=Join-Path $cycle 'mcla.log';$bmp=Assert-ContainedNonReparsePath (Join-Path $cycle 'user/mcla-first-frame.bmp') 'Digital evidence capture';$bmpBytes=[IO.File]::ReadAllBytes($bmp);if($bmpBytes.Length-ne3686454-or$bmpBytes[0]-ne0x42-or$bmpBytes[1]-ne0x4D-or[BitConverter]::ToInt32($bmpBytes,18)-ne1280-or[BitConverter]::ToInt32($bmpBytes,22)-ne720-or[BitConverter]::ToInt16($bmpBytes,28)-ne32){throw 'Digital title BMP format/dimensions are noncanonical.'};$title=[pscustomobject]@{Bmp=[pscustomobject]@{Sha256=(Get-FileHash $bmp -Algorithm SHA256).Hash;Bytes=[long]$bmpBytes.Length;Width=1280;Height=720}};$set=Get-RuntimeLogSet $logPath;Assert-ExactChildren $cycle (@('cache','user')+@($set.Files.name)) 'Digital evidence cycle';Assert-ExactChildren (Join-Path $cycle 'user') @('mcla-first-frame.bmp') 'Digital evidence user root';$log=$set.Text
 $launch=[regex]::Matches($log,[regex]::Escape('KernelState: Preparing module launch...'));$rtl=[regex]::Matches($log,'(?m)^.*RtlLeaveCriticalSection: allowing one or more cross-thread leaves under the explicit compatibility option\r?$');$capture=[regex]::Matches($log,'(?m)^.*MCLA graphics: nontrivial guest frame captured 1280x720, rgb555 bins 4403, luma p05 6, luma p95 239, modal permille 89, nonmodal grid cells 144\r?$');$config=[regex]::Matches($log,'(?m)^.*SDL_CONTROLLER_MATRIX_AUDIT_CONFIG v=1 enabled=1 expected_slot=0 button_mask=F3FF analog_mask=3FF\r?$');$device=[regex]::Matches($log,'(?m)^.*SDL_CONTROLLER_MATRIX_AUDIT_DEVICE v=1 event=assigned slot=0 active_mask=1\r?$');$multi=[regex]::Matches($log,'(?m)^.*SDL_CONTROLLER_MATRIX_AUDIT_MULTIPAD v=1 assigned_mask=1 active_mask=1 rejected=0\r?$');$arm=[regex]::Matches($log,'(?m)^.*SDL_CONTROLLER_MATRIX_AUDIT_ARM v=1 phase=title status=READY active_mask=1 neutral=1\r?$');$inputReady=[regex]::Matches($log,'(?m)^.*SDL_CONTROLLER_MATRIX_AUDIT_INPUT v=1 status=READY neutral=1 rumble_pattern_mask=7 rumble_stop_mask=7\r?$');$fatal=[regex]::Matches($log,'(?m)^.*\[FATAL\] Call to invalid or unregistered function at guest address 0x82554080\r?$');foreach($x in @($launch,$rtl,$capture,$config,$device,$multi,$arm,$inputReady,$fatal)){if($x.Count-ne1){throw 'Digital evidence requires one exact lifecycle/title/input/blocker marker.'}}
 $rumble=[regex]::Matches($log,'(?m)^.*SDL_CONTROLLER_MATRIX_AUDIT_RUMBLE v=1 event=(?<event>start|stop) slot=0 pattern=(?<pattern>left|right|both) result=00000000 supported=1\r?$');$rumbleWant=@('start:left','stop:left','start:right','stop:right','start:both','stop:both');if($rumble.Count-ne6){throw 'Digital evidence rumble matrix is incomplete.'};for($i=0;$i-lt6;$i++){if(($rumble[$i].Groups['event'].Value+':'+$rumble[$i].Groups['pattern'].Value)-cne$rumbleWant[$i]){throw 'Digital evidence rumble order failed.'}}
 $button=[regex]::Matches($log,'(?m)^.*SDL_CONTROLLER_MATRIX_AUDIT_BUTTON v=1 layer=(?<layer>sdl|guest) event=(?<event>down|up) slot=0 bit=(?<bit>[0-9A-F]{4}) seen_mask=(?<mask>[0-9A-F]{4}) source_seq=(?<seq>[1-9][0-9]*)\r?$');$bits=@('0001','0002','0004','0008','0020','0040','0080','0100','0200','1000','2000','4000','8000','0010');$masks=@('0001','0003','0007','000F','002F','006F','00EF','01EF','03EF','13EF','33EF','73EF','F3EF','F3FF');if($button.Count-ne56){throw 'Digital evidence requires the exact 56-record digital surface.'};for($i=0;$i-lt14;$i++){for($j=0;$j-lt4;$j++){$m=$button[$i*4+$j];$layer=if($j%2-eq0){'sdl'}else{'guest'};$event=if($j-lt2){'down'}else{'up'};if($m.Groups['layer'].Value-cne$layer-or$m.Groups['event'].Value-cne$event-or$m.Groups['bit'].Value-cne$bits[$i]-or$m.Groups['mask'].Value-cne$masks[$i]-or[int]$m.Groups['seq'].Value-ne$i+1){throw "Digital button challenge $i is not causal."}}}
 if(-not($launch[0].Index-lt$config[0].Index-and$config[0].Index-lt$device[0].Index-and$device[0].Index-lt$multi[0].Index-and$multi[0].Index-lt$rtl[0].Index-and$rtl[0].Index-lt$arm[0].Index-and$arm[0].Index-lt$capture[0].Index-and$capture[0].Index-lt$rumble[0].Index-and$rumble[5].Index-lt$inputReady[0].Index-and$inputReady[0].Index-lt$button[0].Index-and$button[55].Index-lt$fatal[0].Index)){throw 'Digital evidence chronology is not causal.'}
 if($log-match'(?m)^.*SDL_CONTROLLER_MATRIX_AUDIT_(?:RESUME|ANALOG|FOCUS|HOTPLUG|SUMMARY|FAILURE).*$'){throw 'Digital evidence contains continuation/failure markers.'};$all=[regex]::Matches($log,'(?m)^.*SDL_CONTROLLER_MATRIX_AUDIT_[A-Z_]+.*$');if($all.Count-ne67){throw 'Digital evidence contains an unknown or malformed audit marker.'};$tree=Get-TreeSnapshot $root;if($tree.Hash-cne$canonicalDigitalTreeSha256-or$tree.FileCount-ne11-or$tree.DirectoryCount-ne6-or$tree.Bytes-ne30341991-or$set.Hash-cne$canonicalDigitalLogSetSha256-or$title.Bmp.Sha256-cne$canonicalDigitalCaptureSha256){throw 'Digital evidence differs from the accepted immutable baseline.'};$user=Get-TreeSnapshot (Join-Path $cycle 'user');$cache=Get-TreeSnapshot (Join-Path $cycle 'cache');$cycleTree=Get-TreeSnapshot $cycle
 [pscustomobject]@{RunId=$RunId;Root=$root;LogSet=$set;Title=$title;Tree=$tree;CycleTree=$cycleTree;UserTree=$user;CacheTree=$cache;ButtonCount=56;RumbleCount=6;InputReadyCount=1;FatalCount=1;FatalGuestAddress='0x82554080';Classification='digital-pass_gameplay-transition-blocker';ControlledExitPassed=$false}
}

